//! Conformance vectors (spec/conformance) generated by the independent TS
//! implementation; the Rust normative implementation must agree exactly.

use serde_json::{Map, Value};

fn load(name: &str) -> Value {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../spec/conformance")
        .join(name);
    serde_json::from_str(
        &std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display())),
    )
    .unwrap()
}

#[test]
fn capacity_vectors() {
    let v = load("capacity.json");
    for c in v["valid"].as_array().unwrap() {
        let params: Map<String, Value> = c["params"].as_object().cloned().unwrap_or_default();
        let rt = remit_types::RtTemplate::from_json(&c["returns"])
            .unwrap()
            .bind(&params)
            .unwrap_or_else(|e| panic!("{}: {e}", c["name"]));
        let bits = rt.capacity_bits();
        assert!(
            (bits - c["bits"].as_f64().unwrap()).abs() < 1e-5,
            "{}: rust {bits} vs ts {}",
            c["name"],
            c["bits"]
        );
        assert_eq!(
            rt.capacity_bits_ceil(),
            c["bits_ceil"].as_u64().unwrap(),
            "{}",
            c["name"]
        );
    }
    for c in v["invalid"].as_array().unwrap() {
        let r = remit_types::RtTemplate::from_json(&c["returns"]).and_then(|t| t.bind(&Map::new()));
        let e = r.expect_err(c["name"].as_str().unwrap());
        assert_eq!(e.code(), c["code"].as_str().unwrap(), "{}", c["name"]);
        if let Some(p) = c["path"].as_str() {
            assert_eq!(e.path(), p, "{}", c["name"]);
        }
    }
}

#[test]
fn jcs_vectors() {
    for c in load("jcs.json").as_array().unwrap() {
        assert_eq!(
            remit_wire::jcs::canonicalize(&c["input"]).unwrap(),
            c["canonical"].as_str().unwrap()
        );
    }
}

#[test]
fn remit_id_vectors() {
    for c in load("remit_id.json").as_array().unwrap() {
        let m = remit_wire::Manifest::from_value(c["manifest"].clone()).unwrap();
        assert_eq!(m.remit_id(), c["remit_id"].as_str().unwrap());
        assert_eq!(m.params_sha256(), c["params_sha256"].as_str().unwrap());
    }
}

#[test]
fn sql_vectors() {
    let v = load("sql.json");
    for s in v["accept"].as_array().unwrap() {
        remit_sql::check(s.as_str().unwrap(), &Default::default())
            .unwrap_or_else(|e| panic!("{s}: {e}"));
    }
    for c in v["reject"].as_array().unwrap() {
        let e = remit_sql::check(c["sql"].as_str().unwrap(), &Default::default()).unwrap_err();
        assert_eq!(e.code, c["code"].as_str().unwrap(), "{}", c["sql"]);
    }
}
